impl Solution {
    pub fn count_triplets(n: i32) -> i32 {
        let n = n as usize;
        let mut count = 0;
        for c in 1..=n {
            let c2 = c * c;
            for a in 1..=n {
                if a * a >= c2 {
                    break;
                }
                let b2 = c2 - a * a;
                let b = (b2 as f64).sqrt() as usize;
                if b <= n && b * b == b2 {
                    count += 1;
                }
            }
        }
        count as i32
    }
}

